sys_script_include.script:
var MSSCustodyBulkTradeUtils = Class.create();
MSSCustodyBulkTradeUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    bulkUnavailableUserInformation: function() { //MSSCUSTODY-5172

        try {
            var query = this.getParameter('sysparm_query');
            var enableBulkOption = false;
            var arrMarket = [];
            var outcomesArray = [];
            var arrConfirmTrade = [];
            var arrPutTradeOnHold = [];
            var arrResumeTrade = [];
            var arrSettleTrade = [];
            var arrProcessTradeCancel = [];
            var arrTradeAmend = [];
            var arrTradeAmendandCONF = []; //MSSCUSTODY-7136
            var arrConfAndSettTrade = []; //7420
            var pappApprCanc = []; //MSSCUSTODY-8274
            var pappApprHold = []; //MSSCUSTODY-8274
			var legacySubStatus = [];
			var noAmendReqiredLifecycle =['TradToBeMtchdNtrnly', 'TradCaptrdInErr', 'TradCaptrdPdgApprvl'];
			var noAmendRequired = [];
            var market = gs.getProperty('x_hsb11_mss_c_proc.enableautomatedbulk.market');
            var count = 0;

            // fetching associated markets
            var user1 = new GlideRecord('sys_user');
            user1.get(gs.getUserID());
            usermarket = user1.u_associated_business_markets;


            var grTrade = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_trade');
            grTrade.addEncodedQuery(query);
            grTrade.groupBy('owning_business');
            grTrade.groupBy('trade_lifecycle_status');
            grTrade.query();
            while (grTrade.next()) {
                var flag = false;
                var grTradeOwningBsuiness = grTrade.owning_business.toString();
                var grTrdLifeCycleStatus = grTrade.trade_lifecycle_status.toString();
				var grTrdLegacySubStatus = grTrade.legacy_sub_status.toString();
                //Return false if selected trade record does not find matching market.
                if (market.indexOf(grTradeOwningBsuiness) == -1) {
                    enableBulkOption = 'Creating Bulk is not allowed because it is not yet enabled for the market to which the selected trades belong.';
                    break;
                }

                //Return false if selected trade records are from different markets.
                if (arrMarket.indexOf(grTradeOwningBsuiness.toString()) == -1) {
                    arrMarket.push(grTradeOwningBsuiness.toString());
                    if (arrMarket.length > 1) {
                        enableBulkOption = 'Creating Bulk is not allowed due to different owning business for the selected trades. Kindly select trades with same owning business and try again.';
                        break;
                    }
                }

                //Return false if selected trade records does not find matching market in user profile.
                if (usermarket.indexOf(grTradeOwningBsuiness.toString()) == -1) {
                    enableBulkOption = 'Creating Bulk is not allowed because user does not have access to the owning business of the selected trades.';
                    break;
                }

                //Check BPS table for outcome option 
                var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
                grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + grTradeOwningBsuiness + '^ctac_code=' + grTrdLifeCycleStatus);
                //grBulkEvents.orderBy(grTrdLifeCycleStatus);
                grBulkEvents.query();
                if (grBulkEvents.next()) {
                    flag = true;
                    if (count == 0) {
                        arrConfirmTrade = grBulkEvents.confirm_trade.toString();
                        arrPutTradeOnHold = grBulkEvents.put_trade_on_hold.toString();
                        arrResumeTrade = grBulkEvents.resume_trade.toString();
                        arrSettleTrade = grBulkEvents.settle_trade.toString();
                        arrProcessTradeCancel = grBulkEvents.process_trade_cancellation.toString();
                        arrTradeAmend = grBulkEvents.trade_amend.toString();
                        arrTradeAmendandCONF = grBulkEvents.amend_and_conf.toString(); //MSSCUSTODY-7136
                        arrConfAndSettTrade = grBulkEvents.confirm_and_settle_trade.toString(); //7420
                        pappApprCanc = grBulkEvents.papp_approval_canc.toString(); //MSSCUSTODY-8274
                        pappApprHold = grBulkEvents.papp_approval_hold.toString(); //MSSCUSTODY-8274
						if((noAmendReqiredLifecycle.indexOf(grTrade.trade_lifecycle_status.toString()) > -1) && (grTrade.legacy_sub_status.toString()== 'PCON')) {
							noAmendRequired = true;
						}
						else {
							noAmendRequired = false;
						}



                    } else {
                        if (grBulkEvents.confirm_trade.toString().indexOf("false") > -1) {
                            arrConfirmTrade = grBulkEvents.confirm_trade.toString();
                        }
                        if (grBulkEvents.put_trade_on_hold.toString().indexOf("false") > -1) {
                            arrPutTradeOnHold = grBulkEvents.put_trade_on_hold.toString();
                        }
                        if (grBulkEvents.resume_trade.toString().indexOf("false") > -1) {
                            arrResumeTrade = grBulkEvents.resume_trade.toString();
                        }
                        if (grBulkEvents.settle_trade.toString().indexOf("false") > -1) {
                            arrSettleTrade = grBulkEvents.settle_trade.toString();
                        }
                        if (grBulkEvents.process_trade_cancellation.toString().indexOf("false") > -1) {
                            arrProcessTradeCancel = grBulkEvents.process_trade_cancellation.toString();
                        }
                        if (grBulkEvents.trade_amend.toString().indexOf("false") > -1) {
                            arrTradeAmend = grBulkEvents.trade_amend.toString();
                        }
                        if (grBulkEvents.amend_and_conf.toString().indexOf("false") > -1) { //MSSCUSTODY-7136
                            arrTradeAmendandCONF = grBulkEvents.amend_and_conf.toString();
                        }
                        if (grBulkEvents.confirm_and_settle_trade.toString().indexOf("false") > -1) { //7420
                            arrConfAndSettTrade = grBulkEvents.confirm_and_settle_trade.toString();
                        }
                        if (grBulkEvents.papp_approval_canc.toString().indexOf("false") > -1) { //MSSCUSTODY-8274
                            pappApprCanc = grBulkEvents.papp_approval_canc.toString();
                        }
                        if (grBulkEvents.papp_approval_hold.toString().indexOf("false") > -1) { //MSSCUSTODY-8274
                            pappApprHold = grBulkEvents.papp_approval_hold.toString();
                        }
						if (grBulkEvents.no_amendment_required.toString().indexOf("false") >-1) {
							noAmendRequired = grBulkEvents.no_amendment_required.toString();
						}
                    }
                    count = ++count;
                }

            }
            if (flag == true) {
                outcomesArray.push(arrConfirmTrade, arrPutTradeOnHold, arrResumeTrade, arrSettleTrade, arrProcessTradeCancel, arrTradeAmend, arrTradeAmendandCONF, arrConfAndSettTrade, pappApprCanc, pappApprHold, noAmendRequired); //pushed all the outcome values in temp array     //7420
                if (outcomesArray.indexOf('true') > -1) {
                    gs.info("In here");
                    enableBulkOption = true;
                } else {
                    enableBulkOption = 'Creating Bulk is not allowed for the combination of the lifecycle status for the selected trades. Kindly review the selected trades and try again.';
                }
            }

            return enableBulkOption;

        } catch (e) {
            gs.error("Unexpected error occured during bulk info message from bulkUnavailableUserInformation: " + e.message); //MSSOTIQUBE-1096
        }


    },

    evalBulkOptionTradeList: function() { //MSSCUSTODY-3396
        var query = this.getParameter('sysparm_query');
        var bulkOptionField = this.getParameter('sysparm_bulkOptionField');
        var enableBulkOption = false;
        var arrMarket = [];
        var market = gs.getProperty('x_hsb11_mss_c_proc.enableautomatedbulk.market');

        // fetching associated markets
        var user1 = new GlideRecord('sys_user');
        user1.get(gs.getUserID());
        usermarket = user1.u_associated_business_markets;

        var grTrade = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_trade');
        grTrade.addEncodedQuery(query);
        grTrade.groupBy('owning_business');
        grTrade.groupBy('trade_lifecycle_status');
        //gs.info('bulk upgrade log' + query);
        grTrade.query();
        while (grTrade.next()) {
            gs.info('bulk upgade inside while');
            //Return false if selected task record does not find matching market.
            if (market.indexOf(grTrade.owning_business) == -1) {
                enableBulkOption = false;
                gs.info('bulk upgade owning b prop');
                break;
            }


            //Return false if selected trade records are from different markets.
            if (arrMarket.indexOf(grTrade.owning_business.toString()) == -1) {
                arrMarket.push(grTrade.owning_business.toString());
                if (arrMarket.length > 1) {
                    gs.info('bulk upgade owning b list');
                    enableBulkOption = false;
                    break;
                }
            }


            //Check BPS table for outcome option 
            var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage');
            grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + grTrade.owning_business + '^ctac_code=' + grTrade.trade_lifecycle_status + '^' + bulkOptionField + '=true');
            grBulkEvents.orderBy(bulkOptionField);
            grBulkEvents.query();
            if (grBulkEvents.next()) {
                enableBulkOption = true;
            } else {
                enableBulkOption = false;
                break;
            }

            if (usermarket.indexOf(grTrade.owning_business.toString()) == -1) {
                enableBulkOption = false;
                break;
            }

        }
        return enableBulkOption;

    },

    enablePAPPCancelMenu: function() { //MSSCUSTODY-8274

        var query = this.getParameter('sysparm_query');
        gs.info('enablePAPPContextMenu ' + query);
        var enableBulkOption;
        var getLegacyStatus = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_trade");
        getLegacyStatus.addEncodedQuery(query);
        getLegacyStatus.query();
        while (getLegacyStatus.next()) {
            gs.info('Received legacy_sub_status ' + getLegacyStatus.legacy_sub_status);
            gs.info('Received legacy_status ' + getLegacyStatus.legacy_status);
            if ((getLegacyStatus.legacy_sub_status == 'RCN') && (getLegacyStatus.legacy_status == 'PAPP')) {
                gs.info("Received legacy Loop1");
                enableBulkOption = true;
            } else {
                gs.info("Received legacy Loop2");
                enableBulkOption = false;
                break;
            }
        }
        gs.info("Received legacy Loop2 Final Result " + enableBulkOption);
        return enableBulkOption;
    }, //MSSCUSTODY-8274


    enablePAPPHoldMenu: function() { //MSSCUSTODY-8274

        var query = this.getParameter('sysparm_query');
        gs.info('enablePAPPContextMenu ' + query);
        var enableBulkOption;
        var getLegacyStatus = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_trade");
        getLegacyStatus.addEncodedQuery(query);
        getLegacyStatus.query();
        while (getLegacyStatus.next()) {
            gs.info('Received legacy_sub_status ' + getLegacyStatus.legacy_sub_status);
            gs.info('Received legacy_status ' + getLegacyStatus.legacy_status);
            if ((getLegacyStatus.legacy_sub_status == 'RHG') && (getLegacyStatus.legacy_status == 'PAPP')) {
                gs.info("Received legacy Loop1");
                enableBulkOption = true;
            } else {
                gs.info("Received legacy Loop2");
                enableBulkOption = false;
                break;
            }
        }
        gs.info("Received legacy Loop2 Final Result " + enableBulkOption);
        return enableBulkOption;
    }, //MSSCUSTODY-8274

    bulkUnavailabilityforSingleFiltered: function() {

        try {
            var query = this.getParameter('sysparm_query');

            var grTradeList = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grTradeList.addEncodedQuery(query);
            grTradeList.setLimit(2);
            grTradeList.query();
            return grTradeList.getRowCount(); //return false if the filtered list holds more than one trade

        } catch (e) {
            gs.error("Unexpected error occured during bulk info message from bulkUnavailabilityforSingleFiltered: " + e.message); //MSSOTIQUBE-1096
        }

    },

    createTradeBulkIDUpdated: function() { //MSSCUSTODY-3396
        //Create bulk id from Trade list 
        //Then create MSS Custody Case in linkBulkWitCaseTask and MSS Custody Task and map same bulk id.
        try {
            var tskoutcome = this.getParameter("sysparm_outcome");
            var query = this.getParameter('sysparm_query');
            var count = this.getParameter("sysparm_taskcount"); //MSSCUSTODY-4282 
            var filter = this.getParameter('sysparm_filter'); //MSSCUSTODY-6655

            // Fetch assignment group
            var makerAssignmentGroup = this.getAssignmentGroup('x_hsb11_mss_custod.custody_maker');

            // Initialize and populate bulk transaction record
            var grbulkId = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            grbulkId.initialize();
            grbulkId.setValue('assignment_group', makerAssignmentGroup);
            grbulkId.setValue('assigned_to', gs.getUserID());
            grbulkId.setValue('state', 2);
            grbulkId.setValue('lock', true); // MSSCUSTODY-3992
            grbulkId.setValue('outcome', tskoutcome);
            grbulkId.setValue('active_trade_count', count); //MSSCUSTODY-4282 - active Trade count for validation the linked tasks
            grbulkId.bulk_task_type = 'Maker';
            grbulkId.bulk_type = 'manual_task';
            grbulkId.applied_filter = filter || ''; // MSSCUSTODY-6655

            // Fetch and set template details
            var bulkTemplate = JSON.parse(this.selectTaskTemplate('CUSTODYTTMP00110')); // Template selection
            grbulkId.setValue('short_description', bulkTemplate.shortDescription);
            grbulkId.setValue('description', bulkTemplate.description);


            //MSSCUSTODY-4282 Updating Owning Business In Bulk 
            // Update owning business in bulk
            var grcustodytrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grcustodytrade.addEncodedQuery(query);
            grcustodytrade.query();
            if (grcustodytrade.next()) {
                grbulkId.setValue('owning_business', grcustodytrade.owning_business);
            }
            // Insert and return the sys_id
            var sysId = grbulkId.insert();
            return sysId;
        } catch (error) {
            gs.info('Error while creating bulk ID in createTradeBulkIDUpdated: ' + error.message);
        }

    },

    linkBulkWithCaseTask: function() {
        try {
            var tskoutcome = this.getParameter("sysparm_outcome");
            var query = this.getParameter('sysparm_query');
            var bulkId = this.getParameter('bulk_id');
            var makerAssignmentGroup = this.getAssignmentGroup('x_hsb11_mss_custod.custody_maker');

            var grcustodytrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grcustodytrade.addEncodedQuery(query);
            grcustodytrade.query();
            while (grcustodytrade.next()) {
                var grcustodycase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                grcustodycase.initialize();
                grcustodycase.short_description = 'Manually triggered by Bulk processing';
                grcustodycase.description = 'Manually triggered by Bulk processing';
                grcustodycase.trade_id = grcustodytrade.sys_id;
                grcustodycase.bulk_id = bulkId;
                grcustodycase.triggered_by = '19c79fbb1ba30a10c6ada6c7b04bcbd5';
                grcustodycase.case_status = 'ec34a3731b270a10c6ada6c7b04bcb7a';
                if (tskoutcome == 'Amend Trade') { // fix for 7211- duplicate makers getting created (one from flow and oher from script)
                    grcustodycase.amend_case = 'True';
                }
                grcustodycase.insert();

                //Create Maker Task as part of Amend
                if (tskoutcome == 'Amend Trade') {
                    // var subflowName = 'x_hsb11_mss_c_proc.hsbccustodytrade_amend_maker'; // changes to fix 7211
                    // var inputs = {};
                    // inputs.re_initiate_process = false; 
                    // inputs.case_id = grcustodycase; 
                    // // sn_fd.FlowAPI.getRunner().subflow(subflowName).inBackground().withInputs(inputs).run();

                    // new global.amendTaskCreation().createAmendMakerTask(subflowName,inputs);

                    // if (result) {
                    //     gs.info('Subflow started successfully with execution ID: ' + result.sys_id);
                    // } else {
                    //     gs.error('Failed to start subflow');
                    // }

                    // changes to fix 7211
                    var amendTemplate = new global.JSON.parse(this.selectTaskTemplate('CUSTODYTTMP00126')); //Template selection
                    var grcustodytask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                    grcustodytask.initialize();
                    grcustodytask.trade_task_type = 'Maker';
                    grcustodytask.short_description = amendTemplate.shortDescription; //deparsed from method selectTaskTemplate
                    grcustodytask.description = amendTemplate.description; //deparsed from method selectTaskTemplate
                    grcustodytask.trade_task_type = amendTemplate.trdTaskType;
                    grcustodytask.trade_task_template_id = amendTemplate.templateID;
                    grcustodytask.trade_id = grcustodytrade.sys_id;
                    grcustodytask.trade_case_id = grcustodycase.sys_id;
                    grcustodytask.bulk_id = bulkId;
                    grcustodytask.outcome = 'Amend Trade';
                    grcustodytask.checker_decision = 'Amend';
                    grcustodytask.follow_up = new GlideDateTime();
                    grcustodytask.insert();

                }

                grcustodytrade.case_type = 'manual';
                grcustodytrade.update();
            }
        } catch (ex) {
            gs.info('Error while linking the tasks to Bulk-> LinkBulkWithCaseTask ' + ex.message);
        }

    },


    selectTaskTemplate: function(tempNum) {
        var taskTemplate = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_template');
        taskTemplate.addQuery('template_id', tempNum);
        taskTemplate.query();
        if (taskTemplate.next()) {
            var tempContents = {
                "description": taskTemplate.getValue("template_description"),
                "shortDescription": taskTemplate.getValue("template_short_description"),
                "trdTaskType": taskTemplate.getValue('trade_task_type'),
                "templateID": taskTemplate.getValue('sys_id')
            };
            return JSON.stringify(tempContents);
        }

    },

    getAssignmentGroup: function(roleName) { //MSSCUSTODY-3425
        // var assignmentGroup = '';
        var grMember = new GlideRecord('sys_user_grmember');
        grMember.addQuery('user', gs.getUserID());
        grMember.addEncodedQuery('group.typeLIKE2269529d1b844650ff37eb14b24bcb19');
        grMember.query();

        while (grMember.next()) {
            var grGroupRole = new GlideRecord('sys_group_has_role');
            grGroupRole.addQuery('group', grMember.group);
            grGroupRole.addQuery('role.name', roleName);
            grGroupRole.query();

            if (grGroupRole.next()) {
                assignmentGroup = grGroupRole.group;
                break;
            }

        }

        return assignmentGroup;


    },

    getBandSummary: function() {
        try {
            var bulkId = this.getParameter('sysparm_bulkid');
            var taskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task'); // Replace with your task table name
            taskGR.addQuery('bulk_id', bulkId);
            taskGR.addQuery('trade_task_type', 'Maker'); // Only maker tasks
            taskGR.addQuery('active', true); // Only active tasks
            taskGR.query();

            var bandCounts = {};
            var total = 0;
            while (taskGR.next()) {
                var band = taskGR.trade_id.eligible_band + ''; // Dot-walk to trade's eligible_band
                bandCounts[band] = (bandCounts[band] || 0) + 1;
                total++;
            }
            return JSON.stringify({
                total: total,
                bandCounts: bandCounts
            });
        } catch (e) {
            gs.info('Error while getting band summary MSSCustodyBulkTradeUtils ' + e.message);

        }
    },

    type: 'MSSCustodyBulkTradeUtils'
});
